import React, { useState } from 'react';
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Drawer,
  Avatar,
  Box,
  Typography,
  Chip,
  IconButton,
} from '@mui/material';
import { styled } from '@mui/material/styles';
import { Group, Person } from './types';
import { groups } from './data/mockData';
import CloseIcon from '@mui/icons-material/Close';

const StyledTableRow = styled(TableRow)(({ theme }) => ({
  '&:hover': {
    backgroundColor: theme.palette.action.hover,
    cursor: 'pointer',
  },
}));

const UsageChip = styled(Chip)<{ usage: string }>(({ theme, usage }) => ({
  backgroundColor: 
    usage === 'Permission Sets' ? '#FFF3DC' :
    usage === 'Workflows' ? '#E8F5E9' :
    '#F3E5F5',
  color:
    usage === 'Permission Sets' ? '#975A16' :
    usage === 'Workflows' ? '#1B5E20' :
    '#6A1B9A',
  borderRadius: '4px',
  height: '24px',
}));

const DrawerHeader = styled(Box)(({ theme }) => ({
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'space-between',
  padding: theme.spacing(2),
  borderBottom: `1px solid ${theme.palette.divider}`,
}));

const DrawerContent = styled(Box)(({ theme }) => ({
  padding: theme.spacing(3),
}));

const ConditionSection = styled(Box)(({ theme }) => ({
  marginTop: theme.spacing(3),
  '& > :not(:first-child)': {
    marginTop: theme.spacing(2),
  },
}));

const App: React.FC = () => {
  const [selectedGroup, setSelectedGroup] = useState<Group | null>(null);

  const handleRowClick = (group: Group) => {
    setSelectedGroup(group);
  };

  const handleDrawerClose = () => {
    setSelectedGroup(null);
  };

  return (
    <Box sx={{ p: 3 }}>
      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Name</TableCell>
              <TableCell align="center"># Members</TableCell>
              <TableCell>Usage</TableCell>
              <TableCell>Owner</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {groups.map((group) => (
              <StyledTableRow key={group.id} onClick={() => handleRowClick(group)}>
                <TableCell>{group.name}</TableCell>
                <TableCell align="center">{group.members.length}</TableCell>
                <TableCell>
                  <UsageChip label={group.usage} usage={group.usage} />
                </TableCell>
                <TableCell>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <Avatar src={group.owner.avatar} sx={{ width: 24, height: 24 }} />
                    <Typography>{group.owner.name}</Typography>
                  </Box>
                </TableCell>
              </StyledTableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      <Drawer
        anchor="right"
        open={Boolean(selectedGroup)}
        onClose={handleDrawerClose}
        PaperProps={{
          sx: { width: '400px' },
        }}
      >
        {selectedGroup && (
          <>
            <DrawerHeader>
              <Typography variant="h6">{selectedGroup.name}</Typography>
              <IconButton onClick={handleDrawerClose}>
                <CloseIcon />
              </IconButton>
            </DrawerHeader>
            <DrawerContent>
              <Box>
                <Typography variant="subtitle2" color="text.secondary">
                  Owner
                </Typography>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 1 }}>
                  <Avatar src={selectedGroup.owner.avatar} />
                  <Typography>{selectedGroup.owner.name}</Typography>
                </Box>
              </Box>

              <ConditionSection>
                <Typography variant="subtitle2" color="text.secondary">
                  Members are assigned based on the following conditions:
                </Typography>
                {selectedGroup.conditions.department && (
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      Department is
                    </Typography>
                    <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mt: 1 }}>
                      {selectedGroup.conditions.department.map((dept) => (
                        <Chip key={dept} label={dept} size="small" />
                      ))}
                    </Box>
                  </Box>
                )}
                {selectedGroup.conditions.location && (
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      Location is
                    </Typography>
                    <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mt: 1 }}>
                      {selectedGroup.conditions.location.map((loc) => (
                        <Chip key={loc} label={loc} size="small" />
                      ))}
                    </Box>
                  </Box>
                )}
                {selectedGroup.conditions.position && (
                  <Box>
                    <Typography variant="body2" color="text.secondary">
                      Position is
                    </Typography>
                    <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mt: 1 }}>
                      {selectedGroup.conditions.position.map((pos) => (
                        <Chip key={pos} label={pos} size="small" />
                      ))}
                    </Box>
                  </Box>
                )}
              </ConditionSection>

              <Box sx={{ mt: 3 }}>
                <Typography variant="subtitle2" color="text.secondary">
                  Members ({selectedGroup.members.length})
                </Typography>
                <Box sx={{ mt: 2, display: 'flex', flexDirection: 'column', gap: 2 }}>
                  {selectedGroup.members.map((member) => (
                    <Box
                      key={member.id}
                      sx={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: 1,
                      }}
                    >
                      <Avatar src={member.avatar} />
                      <Box>
                        <Typography>{member.name}</Typography>
                        <Typography variant="body2" color="text.secondary">
                          {member.position}
                        </Typography>
                      </Box>
                    </Box>
                  ))}
                </Box>
              </Box>
            </DrawerContent>
          </>
        )}
      </Drawer>
    </Box>
  );
};

export default App;
